  getr R (reg 10) = Z_to_bv 64 n -> 1 <= n <= 2 ^ 27 ->
  getr R (reg 2) = Z_to_bv 64 sp -> sp mod 16 = 0 -> 0x7fff7f800000 + 16 <= sp -> sp <= 2 ^ 47 -> BGU.writable M (sp - 16) 16 ->
